insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_43_v1'
from (values
('127.248.d.1.A',3,'A Texas company sells machine parts to customers in Mexico and Germany. This is an example of:','["Global business", "A household budget", "A local monopoly", "A neighborhood sale"]'::jsonb,0,'Global business crosses national borders.','original'),
('127.248.d.1.A',4,'Which activity best defines global business?','["Selling only within one city", "Trading goods, services, or capital across national borders", "Printing a school newsletter", "Raising animals on a ranch"]'::jsonb,1,'Global business involves cross-border exchange.','original'),
('127.248.d.1.B',3,'A country that makes only the goods it produces best, then trades for the rest, is using:','["Isolation", "Price fixing", "Specialization", "Rationing"]'::jsonb,2,'Specialization raises efficiency.','original'),
('127.248.d.1.B',4,'One advantage of specialization is that workers and nations can:','["Lower all quality", "Make everything alone", "Avoid all trade", "Produce more with the same resources"]'::jsonb,3,'Focus increases output.','original'),
('127.248.d.1.C',3,'Country A can make cloth at a lower opportunity cost than Country B. Country A has a:','["Comparative advantage", "Tax shelter", "Quota", "Trade deficit"]'::jsonb,0,'Comparative advantage rests on opportunity cost.','original'),
('127.248.d.1.C',4,'Why do nations trade even if one is better at making everything?','["Every nation has equal skills", "Each gains by specializing where its opportunity cost is lowest", "Prices never change", "They are forced to"]'::jsonb,1,'Comparative advantage explains gains from trade.','original'),
('127.248.d.1.D',3,'A mutual fund buys shares of foreign companies but does not run them. This is:','["A subsidy", "Direct investment", "Portfolio investment", "A tariff"]'::jsonb,2,'Portfolio investment is passive ownership.','original'),
('127.248.d.1.D',4,'A company builds its own factory in another country. This is:','["An embargo", "Portfolio investment", "A quota", "Direct investment"]'::jsonb,3,'Direct investment means owning and controlling operations.','original'),
('127.248.d.2.A',3,'The International Monetary Fund mainly works to:','["Promote global monetary cooperation and financial stability", "Print every country''s money", "Control all trade laws", "Set world prices for food"]'::jsonb,0,'The IMF supports stability and lends to countries in need.','original'),
('127.248.d.2.A',4,'A country with a severe balance-of-payments problem may borrow from the:','["Postal service", "International Monetary Fund", "Local chamber of commerce", "Stock exchange only"]'::jsonb,1,'The IMF lends to troubled economies.','original'),
('127.248.d.2.B',3,'One argument for floating exchange rates is that they:','["Never change", "Prevent all trade", "Adjust automatically to market supply and demand", "Are set by one person"]'::jsonb,2,'Markets set floating rates.','original'),
('127.248.d.2.B',4,'One argument against floating exchange rates is that they can:','["Remove all risk", "End inflation", "Fix prices forever", "Create uncertainty for importers and exporters"]'::jsonb,3,'Volatility adds risk.','original'),
('127.248.d.2.C',3,'One argument for fixed exchange rates is that they:','["Give businesses predictable prices", "Require no reserves", "Change daily", "Remove government"]'::jsonb,0,'Stability helps planning.','original'),
('127.248.d.2.C',4,'A drawback of fixed exchange rates is that a government must:','["Ignore its currency", "Hold large reserves to defend the set rate", "Allow free floating", "Stop all imports"]'::jsonb,1,'Defending a peg is costly.','original'),
('127.248.d.2.D',3,'The shared money used in many EU countries, such as Germany and France, is the:','["Peso", "Yen", "Euro", "Franc only"]'::jsonb,2,'The euro replaced many national currencies.','original'),
('127.248.d.2.D',4,'A major benefit of the euro for businesses in member countries is:','["Slower payments", "Higher tariffs", "More currencies to track", "No exchange-rate costs when trading among them"]'::jsonb,3,'A shared currency removes conversion costs.','original'),
('127.248.d.2.E',3,'If $1 equals 17 pesos, how many pesos will $20 buy?','["340", "170", "37", "3,400"]'::jsonb,0,'20 x 17 = 340.','original'),
('127.248.d.2.E',4,'If 1 euro equals $1.10, how many dollars equal 50 euros?','["$550", "$55", "$5.50", "$45"]'::jsonb,1,'50 x 1.10 = 55.','original'),
('127.248.d.2.F',3,'To research a global exchange case, a student should use:','["A guess", "Gossip", "A credible online news or financial site", "A random comment"]'::jsonb,2,'Reliable online sources support research.','original'),
('127.248.d.2.F',4,'When researching an exchange-rate crisis online, the student should:','["Rely on one anonymous post", "Ignore data", "Skip dates", "Compare more than one reliable source"]'::jsonb,3,'Cross-checking improves accuracy.','original'),
('127.248.d.3.A',3,'The foreign exchange market is where participants:','["Buy and sell currencies", "Sell only stocks", "Trade only gold", "Make only loans"]'::jsonb,0,'Forex trades currencies.','original'),
('127.248.d.3.A',4,'Banks play a central role in the foreign exchange market by:','["Making laws", "Quoting prices and trading currencies for clients", "Printing currency", "Setting taxes"]'::jsonb,1,'Banks are the main dealers.','original'),
('127.248.d.3.B',3,'A country''s high inflation usually tends to cause its currency to:','["Disappear", "Stay fixed", "Lose value", "Gain value"]'::jsonb,2,'Inflation erodes purchasing power.','original'),
('127.248.d.3.B',4,'Higher interest rates in a country generally attract foreign investors, which tends to:','["Stop trading", "End inflation", "Lower demand", "Raise demand for that currency"]'::jsonb,3,'Investors need the local currency.','original'),
('127.248.d.3.C',3,'A bank that opens branches in several countries is following a strategy of:','["Global expansion", "Barter", "Local isolation", "Closure"]'::jsonb,0,'Branches extend a bank''s reach.','original'),
('127.248.d.3.C',4,'Rather than opening branches, a bank might enter a foreign market by:','["Ignoring clients", "Forming a partnership or alliance with a local bank", "Ceasing trade", "Printing money"]'::jsonb,1,'Alliances are an alternative strategy.','original'),
('127.248.d.4.A',3,'The loosest level of economic integration, in which members cut tariffs among themselves, is a:','["Customs union", "Economic union", "Free trade area", "Common market"]'::jsonb,2,'A free trade area removes internal tariffs.','original'),
('127.248.d.4.A',4,'A group that removes internal tariffs and also sets one common external tariff is a:','["Trade embargo", "Isolated state", "Free trade area", "Customs union"]'::jsonb,3,'Customs unions share a common external tariff.','original'),
('127.248.d.4.B',3,'A common argument for economic integration is that it:','["Expands markets and lowers costs", "Ends competition", "Raises prices always", "Reduces choices"]'::jsonb,0,'Integration widens trade.','original'),
('127.248.d.4.B',4,'A common argument against economic integration is that it may:','["Lower all prices", "Cost some workers their jobs and reduce national control", "Guarantee growth", "Remove all rules"]'::jsonb,1,'Critics cite job loss and sovereignty.','original'),
('127.248.d.4.C',3,'The organization that governs many European countries economically and politically is the:','["African Union", "League of Nations", "European Union", "Warsaw Pact"]'::jsonb,2,'The EU is the major European organization.','original'),
('127.248.d.4.C',4,'An institution of the European Union that proposes laws and enforces treaties is the:','["World Bank", "Federal Reserve", "Postal Union", "European Commission"]'::jsonb,3,'The Commission is the EU executive.','original'),
('127.248.d.5.A',3,'Money, goods, or services a rich nation gives to a poorer country are called:','["Foreign aid", "Quotas", "Profits", "Tariffs"]'::jsonb,0,'Foreign aid supports development.','original'),
('127.248.d.5.A',4,'Foreign aid can help global trade by:','["Raising tariffs", "Building roads and ports that make trade easier", "Limiting exports", "Closing borders"]'::jsonb,1,'Infrastructure supports commerce.','original'),
('127.248.d.5.B',3,'The General Agreement on Tariffs and Trade (GATT) was created to:','["Raise tariffs", "Create a currency", "Reduce tariffs and other trade barriers", "Ban exports"]'::jsonb,2,'GATT lowered trade barriers.','original'),
('127.248.d.5.B',4,'The World Trade Organization replaced GATT in:','["1945", "2005", "1975", "1995"]'::jsonb,3,'The WTO began operating January 1, 1995.','original'),
('127.248.d.5.C',3,'A tax placed on imported goods is a:','["Tariff", "Quota", "Embargo", "Subsidy"]'::jsonb,0,'Tariffs tax imports.','original'),
('127.248.d.5.C',4,'A limit on the quantity of a good that can be imported is a:','["Subsidy", "Quota", "Tariff", "Dividend"]'::jsonb,1,'Quotas cap volume.','original'),
('127.248.d.5.D',3,'To research a trade dispute online, a student should look for:','["Anonymous posts", "Ads only", "Articles from reliable news and government sources", "Rumors"]'::jsonb,2,'Reliable sources matter.','original'),
('127.248.d.5.D',4,'When reading an online report on a trade issue, a student should check:','["The font", "The ad count", "The page color", "The publisher and the date"]'::jsonb,3,'Source and currency affect reliability.','original'),
('127.248.d.6.A',3,'Governments regulate global business behavior mainly to:','["Protect consumers, workers, and fair competition", "Ban trade", "Limit all profits", "Raise prices only"]'::jsonb,0,'Regulation protects the public.','original'),
('127.248.d.6.A',4,'A reason to regulate multinational companies is that they:','["Have no employees", "Can affect many nations'' economies and environments", "Operate only locally", "Never change anything"]'::jsonb,1,'Large reach calls for oversight.','original'),
('127.248.d.6.B',3,'The Foreign Corrupt Practices Act makes it illegal for U.S. firms to:','["Open foreign offices", "Hire local workers", "Bribe foreign officials to win business", "Export goods"]'::jsonb,2,'The FCPA bans bribery abroad.','original'),
('127.248.d.6.B',4,'A U.S. company pays a foreign official to approve a contract. This violates the:','["Truth in Lending Act", "Fair Labor Standards Act", "Clean Air Act", "Foreign Corrupt Practices Act"]'::jsonb,3,'Bribery is prohibited.','original'),
('127.248.d.6.C',3,'International law influences global business by providing:','["Rules for treaties, contracts, and disputes between nations", "Dress codes", "Local zoning", "School schedules"]'::jsonb,0,'International law frames cross-border conduct.','original'),
('127.248.d.6.C',4,'When two firms in different countries disagree over a contract, they often settle it through:','["A popularity vote", "International arbitration", "A bake sale", "A coin toss"]'::jsonb,1,'Arbitration resolves cross-border disputes.','original'),
('127.248.d.7.A',3,'A manager who ignores local customs when negotiating abroad may:','["Always win", "Lower costs", "Offend partners and lose the deal", "Gain trust"]'::jsonb,2,'Culture shapes business behavior.','original'),
('127.248.d.7.A',4,'Culture affects global business because it shapes:','["Only the weather", "Only taxes", "Only time zones", "How people communicate, negotiate, and buy"]'::jsonb,3,'Culture guides conduct.','original'),
('127.248.d.7.B',3,'Language, religion, and values are all elements of:','["Culture", "Currency", "Inventory", "Tariffs"]'::jsonb,0,'These are cultural elements.','original'),
('127.248.d.7.B',4,'Customs about greetings, gifts, and punctuality are examples of:','["Trade barriers", "Cultural elements", "Exchange rates", "Legal codes"]'::jsonb,1,'Etiquette is part of culture.','original'),
('127.248.d.7.C',3,'A manager preparing to work in another country should:','["Ignore differences", "Rely on stereotypes", "Learn about local customs and language", "Avoid contact"]'::jsonb,2,'Preparation prevents misunderstanding.','original'),
('127.248.d.7.C',4,'Which step helps managers deal with cultural diversity?','["Using only slang", "Banning questions", "Avoiding foreign staff", "Cross-cultural training for employees"]'::jsonb,3,'Training builds awareness.','original'),
('127.248.d.8.A',3,'Faster shipping, the internet, and trade agreements have contributed to the rise of:','["Global linkages", "Closed borders", "Barter only", "Local isolation"]'::jsonb,0,'Technology links markets.','original'),
('127.248.d.8.A',4,'Which development has most strengthened global business linkages?','["Higher tariffs", "The internet and improved transportation", "Border closures", "Slower mail"]'::jsonb,1,'Communication and transport connect firms.','original'),
('127.248.d.8.B',3,'In global trade, the United States is one of the world''s:','["Smallest traders", "Only importers", "Largest importers and exporters", "Only exporters"]'::jsonb,2,'The U.S. is a leading trading nation.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_43_v1'
from (values
('127.248.d.8.B',4,'The United States imports more than it exports in goods. This condition is a trade:','["Embargo", "Quota", "Surplus", "Deficit"]'::jsonb,3,'Imports exceeding exports is a deficit.','original'),
('127.248.d.8.C',3,'An advantage for a U.S. firm entering global markets is:','["Access to many more customers", "Fewer customers", "Higher local rent only", "Less competition always"]'::jsonb,0,'New markets expand sales.','original'),
('127.248.d.8.C',4,'A problem area for U.S. firms entering global markets is:','["No competitors", "Different laws, languages, and currencies", "Identical rules everywhere", "No customers"]'::jsonb,1,'Differences add risk.','original'),
('127.248.d.8.D',3,'The difference between a nation''s exports and imports is its:','["Interest rate", "Tax rate", "Balance of trade", "Inflation rate"]'::jsonb,2,'Balance of trade compares exports and imports.','original'),
('127.248.d.8.D',4,'A country exports $200 billion and imports $250 billion. Its balance of trade is:','["A $450 billion surplus", "Zero", "A $50 billion surplus", "A $50 billion deficit"]'::jsonb,3,'200 - 250 = -50.','original'),
('127.248.d.8.E',3,'Copyrights, trademarks, and patents are forms of:','["Intellectual property", "Real property", "Inventory", "Tangible assets"]'::jsonb,0,'These protect creations.','original'),
('127.248.d.8.E',4,'Counterfeit goods sold abroad hurt a company because they:','["Lower its tariffs", "Take sales and damage its brand and trademark", "Raise its profits", "Protect patents"]'::jsonb,1,'Piracy harms intellectual property owners.','original'),
('127.248.d.8.F',3,'A company advertising in a foreign market might use newspapers, radio, and:','["Telegrams only", "Postcards only", "Television", "Smoke signals"]'::jsonb,2,'Media choices vary by market.','original'),
('127.248.d.8.F',4,'Before choosing advertising media abroad, a marketer should consider:','["The owner''s hobby", "Nothing", "The company''s favorite color", "What media the target audience actually uses"]'::jsonb,3,'Media must reach the audience.','original'),
('127.248.d.8.G',3,'Trade in which producers in developing nations receive fair prices is:','["Fair trade", "Smuggling", "Dumping", "Embargo"]'::jsonb,0,'Fair trade pays producers fairly.','original'),
('127.248.d.8.G',4,'Fair trade standards typically ensure that farmers receive:','["Unlimited hours", "A fair price and safe working conditions", "No payment", "Lower wages"]'::jsonb,1,'Fair trade protects workers.','original'),
('127.248.d.8.H',3,'One benefit of fair trade for producers abroad is:','["Longer hours", "No contracts", "More stable income", "Lower income"]'::jsonb,2,'Fair prices stabilize earnings.','original'),
('127.248.d.8.H',4,'One benefit of fair trade for shoppers at home is:','["Higher risk", "Fewer choices", "Lower quality", "Confidence that products were made ethically"]'::jsonb,3,'Labels show ethical sourcing.','original'),
('127.248.d.9.A',3,'The planning and control of moving goods and information across borders is:','["Global logistics", "Global banking", "Staff training", "Local retailing"]'::jsonb,0,'Logistics manages the flow.','original'),
('127.248.d.9.A',4,'Global logistics includes:','["Only advertising", "Transportation, warehousing, and customs clearance", "Only payroll", "Only hiring"]'::jsonb,1,'Logistics covers the supply chain.','original'),
('127.248.d.9.B',3,'Managing raw materials and parts coming into a factory is:','["Advertising", "Physical distribution", "Materials management", "Banking"]'::jsonb,2,'Materials management handles inputs.','original'),
('127.248.d.9.B',4,'Moving finished goods from the factory to customers is:','["Hiring", "Materials management", "Auditing", "Physical distribution"]'::jsonb,3,'Distribution handles outputs.','original'),
('127.248.d.9.C',3,'A shipper choosing between air and ocean freight considers cost, speed, and:','["Product characteristics", "The weather forecast only", "The driver''s name", "Logos"]'::jsonb,0,'Fragile or perishable goods need different modes.','original'),
('127.248.d.9.C',4,'Fresh flowers sent overseas are best shipped by:','["Ocean freight", "Air freight", "Rail only", "Pipeline"]'::jsonb,1,'Perishables need speed.','original'),
('127.248.d.9.D',3,'A free trade zone is useful because goods can be:','["Destroyed", "Taxed twice", "Stored or processed without paying import duties until they leave", "Banned"]'::jsonb,2,'Zones defer duties.','original'),
('127.248.d.9.D',4,'A company uses a free trade zone mainly to:','["Close its factory", "Print money", "Avoid all laws", "Reduce or delay customs costs"]'::jsonb,3,'Zones lower costs.','original'),
('127.248.d.9.E',3,'To find free trade zones in Texas, a student can search:','["Government and port authority websites", "Social posts only", "Guesses", "Rumors"]'::jsonb,0,'Official sites list zones.','original'),
('127.248.d.9.E',4,'A good way to compare free trade zones statewide is to:','["Skip research", "Make a chart from official sources", "Guess", "Copy an ad"]'::jsonb,1,'Charts organize findings.','original'),
('127.248.d.9.F',3,'Time zones, geography, and work days affect shipments because they can:','["Remove costs", "Eliminate customs", "Delay delivery and communication", "Speed all trades"]'::jsonb,2,'Differences affect scheduling.','original'),
('127.248.d.9.F',4,'A supplier in Asia and a buyer in Texas differ by many time zones. This makes it harder to:','["Print invoices", "Measure weight", "Count stock", "Hold real-time meetings"]'::jsonb,3,'Time differences affect coordination.','original'),
('127.248.d.10.A',3,'Choosing a foreign target market often begins with:','["Researching market size and demand", "Ignoring data", "Picking a random country", "Guessing"]'::jsonb,0,'Research guides selection.','original'),
('127.248.d.10.A',4,'Which factor is important when selecting an export market?','["Spelling of the capital", "Political stability and buying power", "Flag color", "Number of lakes"]'::jsonb,1,'Stability and income matter.','original'),
('127.248.d.10.B',3,'When pricing export goods, a firm must include shipping, tariffs, and:','["Only labor", "Only rent", "Insurance and handling fees", "Only profit"]'::jsonb,2,'Landed costs add up.','original'),
('127.248.d.10.B',4,'Export prices are often higher than domestic prices because of:','["Free shipping", "Lower costs", "No fees", "Added transportation, duties, and documentation"]'::jsonb,3,'Extra steps add cost.','original'),
('127.248.d.10.C',3,'A firm that estimates potential demand using sales data and surveys is using:','["Data-based analytical techniques", "Rumors", "Guesswork", "Wishful thinking"]'::jsonb,0,'Data helps forecast demand.','original'),
('127.248.d.10.C',4,'Which technique estimates how many customers a new market holds?','["A rumor", "Market research with population and income data", "A poem", "A coin flip"]'::jsonb,1,'Data supports estimates.','original'),
('127.248.d.10.D',3,'A company that sells the same product worldwide uses:','["Boycott", "Isolation", "Standardization", "Adaptation"]'::jsonb,2,'Standardization keeps one version.','original'),
('127.248.d.10.D',4,'A fast-food chain changes its menu to fit local tastes. This is:','["Standardization", "Smuggling", "Boycott", "Adaptation of the marketing mix"]'::jsonb,3,'Adaptation tailors to the market.','original'),
('127.248.d.11.A',3,'A global firm''s human resource objectives include hiring, training, and:','["Keeping qualified employees worldwide", "Cutting pay to zero", "Closing offices", "Ignoring laws"]'::jsonb,0,'HR supports global staffing.','original'),
('127.248.d.11.A',4,'HR managers in global firms must also follow:','["No laws", "The employment laws of each country", "Only one country''s laws", "Only tax rules"]'::jsonb,1,'Laws vary by nation.','original'),
('127.248.d.11.B',3,'When a firm goes global, its HR function becomes more complex because it must handle:','["Fewer employees", "Less paperwork", "Different laws, languages, and pay systems", "Identical rules"]'::jsonb,2,'Complexity increases.','original'),
('127.248.d.11.B',4,'A new global duty for HR is arranging:','["Office furniture only", "Local parking", "Holiday sales", "Relocation and cultural training for employees abroad"]'::jsonb,3,'Expatriates need support.','original'),
('127.248.d.11.C',3,'Sources of recruits for jobs abroad include home-country employees, host-country nationals, and:','["Third-country nationals", "Competitors only", "Robots", "Strangers"]'::jsonb,0,'Third-country nationals come from neither country.','original'),
('127.248.d.11.C',4,'Hiring local workers in the host country is called hiring:','["Interns only", "Host-country nationals", "Third-country nationals", "Expatriates"]'::jsonb,1,'Locals know the market.','original'),
('127.248.d.11.D',3,'Training for employees in different countries should consider:','["One universal slang", "Only the home office''s habits", "Local culture and learning styles", "Nothing"]'::jsonb,2,'Training must fit the audience.','original'),
('127.248.d.11.D',4,'A similarity in training across countries is the need to:','["Skip goals", "Skip safety", "Ignore laws", "Teach job skills and company standards"]'::jsonb,3,'Core skills apply everywhere.','original'),
('127.248.d.12.A',3,'Assessing your personal global marketability means identifying your skills, languages, and:','["International experience", "Favorite foods", "Age only", "Hair color"]'::jsonb,0,'These make you attractive globally.','original'),
('127.248.d.12.A',4,'Which skill increases a job seeker''s global marketability?','["Refusing travel", "Fluency in more than one language", "Avoiding teams", "Ignoring cultures"]'::jsonb,1,'Language skills open doors.','original'),
('127.248.d.12.B',3,'To find job openings abroad, a person can use:','["Rumors", "Guesses", "International job boards and multinational company sites", "Mail only"]'::jsonb,2,'Online listings cover jobs.','original'),
('127.248.d.12.B',4,'An appropriate employment opportunity abroad should match the person''s:','["Shoe size", "Hobbies only", "Favorite color", "Skills, goals, and visa eligibility"]'::jsonb,3,'Fit and eligibility matter.','original'),
('127.248.d.12.C',3,'When comparing job offers abroad, you should look at salary, benefits, and:','["Cost of living and relocation support", "Logo", "Parking", "Weather only"]'::jsonb,0,'Total package matters.','original'),
('127.248.d.12.C',4,'Two offers have the same pay, but one city costs much more to live in. The better deal is probably the:','["Higher-cost city", "Lower-cost city", "Neither", "Either, with no difference"]'::jsonb,1,'Real income depends on living costs.','original'),
('127.248.d.12.D',3,'An orientation manual for someone moving abroad should include:','["Competitor lists", "Only jokes", "Local customs, laws, and housing information", "Blank pages"]'::jsonb,2,'It prepares newcomers.','original'),
('127.248.d.12.D',4,'Which section best belongs in a relocation orientation manual?','["A movie review", "A sports score", "A recipe book", "Emergency contacts and healthcare information"]'::jsonb,3,'Safety information is essential.','original'),
('127.248.d.13.A',3,'Learning to listen and share credit with a team is:','["Building interpersonal and team skills", "Working alone", "Wasting time", "Avoiding work"]'::jsonb,0,'Soft skills matter.','original'),
('127.248.d.13.A',4,'A team member who respects other cultures and shares work fairly shows:','["Rudeness", "Effective team-building skills", "Disinterest", "Poor teamwork"]'::jsonb,1,'Respect builds teams.','original'),
('127.248.d.13.B',3,'Joining a student business club as an officer is a:','["Hiring practice", "Audit", "Leadership activity", "Tariff"]'::jsonb,2,'Offices build leadership.','original'),
('127.248.d.13.B',4,'Attending a career fair for international jobs is a:','["Disciplinary action", "Layoff", "Tax filing", "Career development activity"]'::jsonb,3,'Career fairs explore options.','original'),
('127.249.d.1.A',3,'A virtual business office provides services to clients mainly through:','["Internet and phone communication", "Postal pigeons", "Walk-in traffic", "In-person visits only"]'::jsonb,0,'Virtual offices work remotely.','original'),
('127.249.d.1.A',4,'A typical duty of a virtual business office is:','["Building houses", "Handling email, scheduling, and documents for clients", "Selling fuel", "Delivering pizza"]'::jsonb,1,'Administrative support is common.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
